// Synthetic pure function: groups invoices by calendar quarter.
function groupInvoicesByQuarter(invoices) {
  const groups = {};

  for (const invoice of invoices) {
    const date = new Date(invoice.date);
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth(); // 0-11
    const quarter = Math.floor(month / 3) + 1;
    const key = `${year}-Q${quarter}`;

    if (!groups[key]) {
      groups[key] = { quarter: key, invoices: [], total: 0 };
    }

    groups[key].invoices.push(invoice);
    groups[key].total += invoice.amount;
  }

  return Object.values(groups).sort((a, b) => a.quarter.localeCompare(b.quarter));
}

module.exports = { groupInvoicesByQuarter };
